const entrada = items[0].json;

// Sanitiza texto para evitar erro 132018 do WhatsApp
const nome = String(entrada.nome || "")
  .replace(/\s+/g, " ")
  .trim();

const mensagemCompleta = `Olá, ${nome}! Tudo bem?

Passando para lembrar que o contrato referente ao seu atendimento já foi enviado e ainda está aguardando sua assinatura.

Assim que o documento for assinado, poderemos dar continuidade aos próximos passos do seu processo.`;

const redisMemoryMessage = JSON.stringify({
  type: "ai",
  data: {
    content: mensagemCompleta,
    tool_calls: [],
    invalid_tool_calls: [],
    additional_kwargs: {},
    response_metadata: {}
  }
});

const body = {
  messaging_product: "whatsapp",
  to: String(entrada.telefone),
  type: "template",
  template: {
    name: "followup_assinatura_contrato",
    language: {
      code: "pt_BR"
    },
    components: [
      {
        type: "body",
        parameters: [
          {
            type: "text",
            text: nome
          }
        ]
      }
    ]
  }
};

return [{
  json: {
    participant_id: entrada.id,
    telefone: entrada.telefone,
    nome: nome,
    template_name: "followup_assinatura_contrato",

    // Preview da mensagem
    mensagem_completa: mensagemCompleta,

    // Compatível com Redis Chat Memory
    redis_memory_message: redisMemoryMessage,

    // Body para enviar ao WhatsApp
    resultado: body
  }
}];

// Guard do retorno combinado (lembrete manual do CRM).
// Marca cada candidato desta cobranca. Quem tem retorno combinado aberto
// (agendado, processando, enviado ou incerto) nao recebe cobranca.
// O item segue intacto: so ganha o campo guard_retorno_combinado.
// Itens sem id (ex.: resposta vazia do banco) seguem como antes.
const lista = $('Leads com retorno combinado aberto').first().json.retornos_abertos_por_lead;
if (lista === null || lista === undefined || typeof lista !== 'object' || Array.isArray(lista)) {
  throw new Error('Guard do retorno combinado: lista de retornos abertos invalida. Nenhuma cobranca enviada nesta execucao.');
}
return $input.all().map((item, i) => {
  const id = item.json && item.json.id != null ? String(item.json.id) : null;
  const status = id ? lista[id] : undefined;
  let decisao = 'liberado';
  if (status) {
    decisao = String(status).includes('incerto') ? 'retorno_incerto_revisao_humana' : 'retorno_combinado_aberto';
  }
  return { json: { ...item.json, guard_retorno_combinado: decisao }, pairedItem: { item: i } };
});
